import * as chai from 'chai';
import 'mocha';
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';

const expect = chai.expect;

const PKG_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const PACKAGES = resolve(PKG_ROOT, '..');
const REPO_ROOT = resolve(PACKAGES, '..');
const ETC_DIR = join(PKG_ROOT, 'etc');
const UPDATE = process.env.AUTHN_API_SNAPSHOT === 'update';
if (UPDATE && process.env.CI) {
  throw new Error('AUTHN_API_SNAPSHOT=update rewrites the snapshots and must not run in CI.');
}
const CHECK = 'npm run api:check --workspace=packages/authn';
const REGENERATE = `AUTHN_API_SNAPSHOT=update ${CHECK}`;

interface Entry {
  snapshot: string;
  title: string;
  files: string[];
}

const posix = (p: string) => p.split('\\').join('/');

function listTs(dir: string): string[] {
  const out: string[] = [];
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) out.push(...listTs(p));
    else if (e.name.endsWith('.ts')) out.push(p);
  }
  return out;
}

const ENTRIES: Entry[] = [
  { snapshot: 'authn-contracts.api.md', title: '@spinajs/authn/contracts', files: listTs(join(PACKAGES, 'authn', 'src', 'contracts')) },
  { snapshot: 'authn-session.api.md', title: '@spinajs/authn-session contracts', files: [join(PACKAGES, 'authn-session', 'src', 'contracts.ts')] },
  { snapshot: 'authn-oidc.api.md', title: '@spinajs/authn-oidc contracts', files: [join(PACKAGES, 'authn-oidc', 'src', 'contracts.ts')] },
  { snapshot: 'authn-http.api.md', title: '@spinajs/authn-http api', files: [join(PACKAGES, 'authn-http', 'src', 'api.ts')] },
].map((e) => ({ ...e, files: e.files.map((f) => posix(relative(REPO_ROOT, f))).sort() }));

const lf = (s: string) => s.replace(/\r\n?/g, '\n');

// transpileDeclaration needs no build and no type resolution, so the result does not depend on build order.
function declare(file: string): { text: string; errors: string[] } {
  const r = ts.transpileDeclaration(lf(readFileSync(join(REPO_ROOT, file), 'utf8')), {
    fileName: file,
    reportDiagnostics: true,
    // strictNullChecks as in the repo tsconfig, so the output matches the TS 7 build's .d.ts.
    compilerOptions: { strictNullChecks: true, removeComments: false, declarationMap: false, newLine: ts.NewLineKind.LineFeed },
  });
  const errors = (r.diagnostics ?? []).map((d) => {
    const at = d.file && d.start !== undefined ? d.file.getLineAndCharacterOfPosition(d.start) : null;
    return `${file}${at ? `(${at.line + 1},${at.character + 1})` : ''}: ${ts.flattenDiagnosticMessageText(d.messageText, '\n')}`;
  });
  const text = lf(r.outputText)
    .replace(/^\/\/# sourceMappingURL=.*$/gm, '')
    .trimEnd();
  return { text, errors };
}

function render(entry: Entry): string {
  const head = [`# API snapshot: ${entry.title}`, '', 'Generated by `packages/authn/test/contracts/api-snapshot.test.ts` from', '`ts.transpileDeclaration` of the files below. Do not edit by hand.', '', `Check: \`${CHECK}\``, '', `Regenerate: \`${REGENERATE}\``, '', 'These contracts freeze at gate G1. After G1 a change to this file needs an', 'RFC in `docs/plans/authz-v3-rfc/` (plan §1.3).'];
  const body = entry.files.flatMap((f) => ['', `## \`${f}\``, '', '```ts', declare(f).text, '```']);
  return [...head, ...body, ''].join('\n');
}

// Line diff over the longest common subsequence, printed as hunks with two lines of context.
function diff(committed: string, generated: string): string {
  const a = committed.split('\n');
  const b = generated.split('\n');
  const lcs = Array.from({ length: a.length + 1 }, () => new Array<number>(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      lcs[i][j] = a[i] === b[j] ? lcs[i + 1][j + 1] + 1 : Math.max(lcs[i + 1][j], lcs[i][j + 1]);
    }
  }
  const ops: { op: ' ' | '-' | '+'; line: string; at: number }[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) ops.push({ op: ' ', line: a[i++], at: j++ });
    else if (i < a.length && (j === b.length || lcs[i + 1][j] >= lcs[i][j + 1])) ops.push({ op: '-', line: a[i++], at: j });
    else ops.push({ op: '+', line: b[j], at: j++ });
  }
  const keep = ops.map((_, k) => ops.slice(Math.max(0, k - 2), k + 3).some((x) => x.op !== ' '));
  const out: string[] = [];
  ops.forEach((o, k) => {
    if (!keep[k]) return;
    if (k === 0 || !keep[k - 1]) out.push(`@@ generated line ${o.at + 1} @@`);
    out.push(`${o.op} ${o.line}`);
  });
  return out.join('\n');
}

describe('authn api snapshot', () => {
  it('every frozen contract file emits declarations without isolated-declaration errors', () => {
    const files = ENTRIES.flatMap((e) => e.files);
    expect(files).to.include.members(['packages/authn/src/contracts/index.ts', 'packages/authn/src/contracts/principal.ts']);
    expect(files.flatMap((f) => declare(f).errors)).to.deep.eq([]);
  });

  for (const entry of ENTRIES) {
    it(`etc/${entry.snapshot} matches the declarations of ${entry.title}`, () => {
      const path = join(ETC_DIR, entry.snapshot);
      const actual = render(entry);
      const committed = existsSync(path) ? lf(readFileSync(path, 'utf8')) : null;
      if (committed === actual) return;
      if (UPDATE) {
        mkdirSync(ETC_DIR, { recursive: true });
        writeFileSync(path, actual);
        return;
      }
      const why = committed === null ? `${posix(relative(REPO_ROOT, path))} is missing.` : `${posix(relative(REPO_ROOT, path))} differs from the declarations (- committed, + generated):\n\n${diff(committed, actual)}`;
      expect.fail(`${why}\n\nA frozen authn contract changed. After G1 this needs an RFC in docs/plans/authz-v3-rfc/.\nRegenerate: ${REGENERATE}`);
    });
  }

  it('etc holds no snapshot without a source entry', () => {
    const known = ENTRIES.map((e) => e.snapshot);
    const found = existsSync(ETC_DIR) ? readdirSync(ETC_DIR).filter((f) => f.endsWith('.api.md')) : [];
    expect(found.filter((f) => !known.includes(f))).to.deep.eq([]);
  });
});
